        LANGUAGE_WRAPPER = 'A rectangular picture frame $ABCD$ is to be made. Inside the frame, a decorative parallelogram-shaped inlay $PQRS$ is placed. The vertices of the inlay $P, Q, R, S$ must touch the edges of the frame $\\overline{AB}, \\overline{BC}, \\overline{CD}, \\overline{DA}$ respectively, with $P$ on $\\overline{AB}$, $Q$ on $\\overline{BC}$, and so on. A designer specifies the dimensions of the inlay: its adjacent side lengths are $PQ = {s1}$ and $QR = {s2_str}$, and its area is ${area}$ square units. To position the inlay, the designer also specifies that the ratio of the distances from corner $B$ to the vertices $P$ and $Q$ must be $PB/BQ = {k_num}/{k_den}$. What is the perimeter of the picture frame $ABCD$?'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def format_sqrt(n):
    if n <= 0:
        return '0'
    i = math.isqrt(n)
    if i * i == n:
        return str(i)
    limit = math.isqrt(n)
    factor = 1
    for j in range(limit, 1, -1):
        if n % (j * j) == 0:
            factor = j
            break
    if factor == 1:
        return f'\\sqrt{{{n}}}'
    rem = n // (factor * factor)
    return f'{factor}\\sqrt{{{rem}}}'

def generator(rng):
    ppt = [(3, 4, 5), (5, 12, 13), (8, 15, 17), (7, 24, 25), (20, 21, 29)]

    for _ in range(100): # Retry loop
        x, y, z = rng.choice(ppt)
        m = rng.randint(1, 4)

        if rng.random() < 0.5:
            b, c = m * x, m * y
        else:
            b, c = m * y, m * x

        s1 = m * z

        for _ in range(50): # Inner loop for a, d
            a = rng.randint(2, 25)
            d = rng.randint(2, 25)

            if a == d or a in (b, c) or d in (b, c):
                continue

            s2_sq = a * a + d * d
            if s2_sq == s1 * s1: # Avoid rhombus case
                continue

            if a * d == b * c: # Avoid inscribed rectangle case
                continue

            # All conditions met, we have a valid set
            area = a * d + b * c
            g = math.gcd(b, c)
            k_num = b // g
            k_den = c // g
            s2_str = format_sqrt(s2_sq)
            perimeter = 2 * (a + b + c + d)

            return {
                's1': s1,
                's2_str': s2_str,
                'area': area,
                'k_num': k_num,
                'k_den': k_den,
                'perimeter': perimeter
            }
    # If we exhausted retries, call recursively to reset choices.
    return generator(rng)

        import math

def verifier(assign):
    s1 = assign['s1']
    s2_str = assign['s2_str']
    area = assign['area']
    k_num = assign['k_num']
    k_den = assign['k_den']
    ans = assign['perimeter']

    # Basic validation
    if not (s1 > 0 and area > 0 and k_num > 0 and k_den > 0):
        return False, None

    # Parse s2_str to get s2_sq
    try:
        if '\\sqrt' in s2_str:
            if s2_str.startswith('\\sqrt'):
                F = 1
                R_str = s2_str[6:-1]
            else:
                parts = s2_str.split('\\sqrt{')
                F = int(parts[0])
                R_str = parts[1][:-1]
            R = int(R_str)
            s2_sq = F * F * R
        else:
            s2_sq = int(s2_str) ** 2
    except (ValueError, IndexError):
        return False, None # Invalid s2_str format

    # Step 1: Solve for b and c
    s1_sq = s1 * s1
    k_sum_sq = k_num * k_num + k_den * k_den
    if k_sum_sq == 0 or s1_sq % k_sum_sq != 0:
        return False, None # b,c would not be integers
    m_sq = s1_sq // k_sum_sq
    m = math.isqrt(m_sq)
    if m * m != m_sq:
        return False, None # b,c would not be integers

    b = m * k_num
    c = m * k_den

    # Step 2: Solve for a+d
    bc = b * c
    if area <= bc:
        return False, None # ad would be non-positive
    ad = area - bc

    a_plus_d_sq = s2_sq + 2 * ad
    if a_plus_d_sq < 0:
        return False, None
    a_plus_d = math.isqrt(a_plus_d_sq)
    if a_plus_d * a_plus_d != a_plus_d_sq:
        return False, None # a+d is not an integer

    # Step 3: Calculate perimeter
    perimeter = 2 * (a_plus_d + b + c)

    # Difficulty check: ensure it's not the simpler rhombus case
    if s1_sq == s2_sq:
        return False, None # This is a rhombus, which is an easier special case.

    # Final answer check
    return perimeter == ans, ans


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
